create temp table novas (p uuid, d date);
) v(p, os) cross join unnest(v.os) o;
delete from escala_folgas where tipo = 'folga' and data between '2026-12-07' and '2027-01-31' and colaborador_loja_id in (select distinct p from novas);
select p, d, 'folga', 'Escala 5x2 · grupos com 3 dias fixos', 'Escala automática' from novas
on conflict (colaborador_loja_id, data) do nothing;
create temp table novas_g (g uuid, d date);
) v(g, os) cross join unnest(v.os) o;
delete from escala_grupo_folgas where data between '2026-12-07' and '2027-01-31' and grupo_id in (select distinct g from novas_g);
select (select count(*) from novas) novas,
 (select count(*) from escala_folgas f where f.tipo='folga' and f.data between '2026-12-07' and '2027-01-31' and f.colaborador_loja_id in (select p from novas)) gravadas,
 (select count(*) from escala_grupos where dia_3 is not null) grupos_com_3_dias;
